// internal/distributed/proxy/httpserver/handler_v2.go line 842-892
func (h *HandlerV2) handleQuery(ctx context.Context, req *restful.QueryRequest) (*restful.QueryResponse, error) {
    // Parse filter expression - empty/null filter treated as no filter
    expr := req.GetFilter()
    if expr == nil || expr.GetStringValue() == "" {
        // Empty filter means match all - this is by design
        expr = nil
    }

    // Build query request
    queryReq := &queryReq{
        collectionName: req.CollectionName,
        expr: expr,
        outputFields: req.OutputFields,
        limit: req.Limit,
        offset: req.Offset,
    }

    // Execute query with empty expression = return all entities
    return h.queryEngine.Query(ctx, queryReq)
}
